public class BoundsFinderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Bounds<Integer> nums = BoundsFinder.of(java.util.List.of(3, 1, 4, 1, 5));
        check("integer min", 1, nums == null ? null : nums.min());
        check("integer max", 5, nums == null ? null : nums.max());
        check("record toString", "Bounds[min=1, max=5]", String.valueOf(nums));
        Bounds<String> words = BoundsFinder.of(java.util.List.of("pear", "apple", "fig"));
        check("string min", "apple", words == null ? null : words.min());
        check("string max", "pear", words == null ? null : words.max());
        Bounds<Integer> single = BoundsFinder.of(java.util.List.of(42));
        check("single element is both min and max", "Bounds[min=42, max=42]", String.valueOf(single));
        check("empty list gives null", null, BoundsFinder.of(java.util.List.<Integer>of()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

