record Bounds<T>(T min, T max) { }

public class BoundsFinder {

    public static <T extends Comparable<T>> Bounds<T> of(java.util.List<T> items) {
        if (items.isEmpty()) {
            return null;
        }
        T min = items.get(0);
        T max = items.get(0);
        for (T item : items) {
            if (item.compareTo(min) < 0) {
                min = item;
            }
            if (item.compareTo(max) > 0) {
                max = item;
            }
        }
        return new Bounds<>(min, max);
    }
}
